import { writeText, yamlScalar } from './io.ts'
import { overlayPath } from './paths.ts'
import type { PluginManifest } from './types.ts'

export function renderOverlay(plugin: PluginManifest): string {
  const lines = [
    '# generated by dshx — do not commit',
    '# --patch does not change Loader baseUrl; plugin name must be absolute',
    '- insert:',
    `    - id: ${plugin.id}`,
    `      name: ${yamlScalar(plugin.entryAbs)}`,
  ]
  if (plugin.config && Object.keys(plugin.config).length > 0) {
    lines.push('      config:')
    for (const [key, value] of Object.entries(plugin.config)) {
      lines.push(`        ${key}: ${JSON.stringify(value)}`)
    }
  }
  lines.push('')
  return lines.join('\n')
}

export function writeOverlay(root: string, plugin: PluginManifest): string {
  const path = overlayPath(root, plugin.id)
  writeText(path, renderOverlay(plugin))
  return path
}
